  "Blueprint": "المخطط الهندسي",
  "Blueprint’s guidance after 40: strength train 2–3 times a week, cover the major muscle groups with compound movements and gradually increase reps or load. Start with bodyweight if new.": "إرشادات Blueprint بعد سن الأربعين: تدرّب على القوة 2–3 مرات أسبوعيًا، وغطِّ مجموعات العضلات الرئيسية بحركات مركبة، وزد التكرارات أو الحمل تدريجيًا. وابدأ بوزن الجسم إذا كنت مبتدئًا.",
  "Blueprint's title block names the exercise, and it dimensions steps and boxes only when there is one. Doodle has jokes for each kind of exercise and tallies the reps as they're counted; its speech bubble no longer covers the figure.": "يسمي قالب عنوان المخطط الهندسي التمرين، ويحدد أبعاد الدرجات والصناديق فقط عند وجود أحدها. وتحتوي الخربشة على نكات لكل نوع تمرين وتحسب التكرارات أثناء عدها؛ ولم تعد فقاعة الكلام تغطي الشخصية.",
  "Bobby Maximus": "Bobby Maximus",
  "Body straight; squeeze the glutes and brace the abs.": "الجسم مستقيم؛ اضغط عضلات المؤخرة وشد البطن.",
