  "Born Fitness": "Born Fitness",
  "Both checks are true and the session count is met. Move up when you want.": "تحقق الفحصان وتم استيفاء عدد الجلسات. انتقل للأعلى متى أردت.",
  "Both speaking paces share cached audio, and repeated interval cues reuse the same clips.": "تشترك سرعتا التحدث في الصوت المخزن، وتعيد إشارات الفواصل المتكررة استخدام المقاطع نفسها.",
  "Bound back. Build distance before adding speed.": "اقفز للخلف. زد المسافة قبل زيادة السرعة.",
  "Bound sideways to the left and land on the left leg only.": "اقفز جانبًا إلى اليسار واهبط على الساق اليسرى فقط.",
  "Box step-up": "الصعود على الصندوق",
  "bpm drop": "انخفاض النبض",
  "Brace abs and glutes; press straight up until the arms are straight.": "شد البطن وعضلات المؤخرة؛ واضغط للأعلى حتى تستقيم الذراعان.",
  "Breathe in slowly as you lift your chest and tailbone.": "شهيق ببطء أثناء رفع صدرك وعظم الذيل.",
  "Breathe out: round the back, tuck chin and tailbone.": "ازفر: قوّس ظهرك واسحب الذقن وعظم الذيل.",
  "Breathe slowly": "تنفس ببطء",
  "Breathe slowly and rhythmically; hold for the target duration without swinging.": "تنفس ببطء وبانتظام، واثبت للمدة المستهدفة دون تأرجح.",
  "Breathe steadily throughout the hold.": "تنفس بانتظام طوال مدة الثبات.",
  "Breathing to Heal": "Breathing to Heal",
  "Brian Schmitt Fitness": "Brian Schmitt Fitness",
  "Bring the hands together in front of the chest as if hugging a tree; squeeze 1 s.": "اجمع اليدين أمام الصدر كأنك تعانق شجرة؛ واضغط ثانية واحدة.",
  "Bring your hands back slowly. Do the same number of reps on both sides.": "أعد يديك ببطء. ونفّذ العدد نفسه من التكرارات على الجانبين.",
  "Brisk": "سريع",
  "Brisk marching in place": "مشي سريع في المكان",
  "Bryan": "براين",
  "Bryan 2025 (Galpin)": "براين 2025 (جالبين)",
  "Bryan 2025: 2 × 5": "براين 2025: 2 × 5",
  "Bryan 2025: 2 × 5–8": "براين 2025: 2 × 5–8",
  "Bryan 2025: flexibility set": "براين 2025: مجموعة المرونة",
  "Bryan 2025: rotational power": "براين 2025: القوة الدورانية",
  "Bryan 2026: heavy pull → jumps": "براين 2026: سحب ثقيل ← قفزات",
  "Bryan 2026: jumps for fast-twitch power": "براين 2026: قفزات لقوة الألياف سريعة الانقباض",
  "Bryan adds a weighted vest during Zone 2 walks and hikes to increase axial bone loading safely.": "يضيف براين سترة مثقلة أثناء مشي المنطقة 2 والتنزه لزيادة التحميل المحوري للعظام بأمان.",
  "Bryan calls the phone the worst trigger for bad posture. Hold it at eye level and put the top of your monitor at eye level too.": "يصف براين الهاتف بأنه أسوأ مسبب للوضعية السيئة. أمسكه على مستوى العين، وضع أعلى الشاشة على مستوى العين أيضًا.",
  "Bryan calls this technical and was taught it for his own diagnosed condition. Stay gentle, and stop if you get dizziness, tingling or a headache.": "يعتبر براين هذا التمرين تقنيًا وتعلمه لحالته المشخصة. وكن لطيفًا، وتوقف إذا أصبت بدوار أو تنميل أو صداع.",
  "Bryan did 1 × 10 in 2023. His 2025 Galpin session includes Nordic curls in the strength block. They protect against hamstring strains.": "أدى براين 1 × 10 في 2023. وتتضمن جلسة جالبين 2025 ثني الفخذ النوردي في كتلة القوة. وهو يحمي من إجهاد عضلات الفخذ الخلفية.",
  "Bryan does “butterfly pulls” with a resistance band, 1 × 15. Most write-ups describe it as a band chest fly; watch his clip to copy his exact version.": "يؤدي براين «سحب الفراشة» بشريط مقاومة، 1 × 15. وتصفه معظم الكتابات بفتح الصدر بالمطاط؛ شاهد مقطعه لنسخ نسخته بالضبط.",
  "Bryan does 3 × 10 per leg, learned from Ben Patrick, the Knees-Over-Toes coach working with him on his 2026 dunk project. It builds the inner quad (VMO) and knee resilience.": "يؤدي براين 3 × 10 لكل ساق، وتعلّمها من بن باتريك، مدرب «الركبتين فوق أصابع القدم» الذي يعمل معه في مشروع الدانك 2026. تبني عضلة الفخذ الداخلية (VMO) ومتانة الركبة.",
  "Bryan does both grips": "يؤدي براين القبضتين",
  "Bryan does both. His 2025 Galpin session includes them in the strength block at 2 × 5–8. His official beginner list uses assisted pull-ups.": "يؤدي براين القبضتين. وتتضمنهما جلسة جالبين 2025 في كتلة القوة بـ2 × 5–8. وتستخدم قائمته الرسمية للمبتدئين العقلة بمساعدة.",
  "Bryan does the Pallof press in his 2025 session with Dr. Andy Galpin. It trains the trunk to resist twisting.": "يؤدي براين ضغط بالوف في جلسة 2025 مع الدكتور آندي جالبين. ويدرّب الجذع على مقاومة اللف.",
  "Bryan does tibialis raises (1 × 25, single-leg in his list). His 2026 dunk notes mention limited ankle dorsiflexion. This exercise works on that movement.": "يؤدي براين رفع الظنبوب (1 × 25، وبساق واحدة في قائمته). وتذكر ملاحظات الدانك 2026 محدودية ثني الكاحل. ويعمل هذا التمرين على تلك الحركة.",
  "Bryan has been training to dunk at 49 since July 2026, using heavy lifts with jumps between sets. He says he needs more fast-twitch fibres and faster force development, and warns about Achilles risk from landing forces. Learn to land before working on height.": "يتدرب براين على الدانك في سن 49 منذ يوليو 2026، باستخدام رفعات ثقيلة مع قفزات بين المجموعات. يقول إنه يحتاج إلى ألياف سريعة الانقباض وتطوير أسرع للقوة، ويحذر من خطر وتر العرقوب بسبب قوى الهبوط. تعلّم الهبوط قبل العمل على الارتفاع.",
  "Bryan Johnson": "Bryan Johnson",
  "Bryan Johnson · Jul 18, 2023": "براين جونسون · 18 يوليو 2023",
  "Bryan Johnson · Jun 7, 2023": "براين جونسون · 7 يونيو 2023",
  "Bryan Johnson · May 26, 2026": "براين جونسون · 26 مايو 2026",
  "Bryan Johnson · Nov 18, 2024": "براين جونسون · 18 نوفمبر 2024",
  "Bryan Johnson · Sep 7, 2023": "براين جونسون · 7 سبتمبر 2023",
  "Bryan Johnson (@bryan_johnson)": "Bryan Johnson (@bryan_johnson)",
  "Bryan Johnson: official pages": "براين جونسون: الصفحات الرسمية",
