  "Choose movements from this list for your intervals, then record them in the interval block.": "اختر حركات من هذه القائمة لفتراتك، ثم سجّلها في كتلة الفواصل.",
  "Choose the language for the app, the exercise instructions and the coach. You can change it later in Settings.": "اختر لغة التطبيق وتعليمات التمارين والمدرب. يمكنك تغييرها لاحقًا في الإعدادات.",
