  "Cobra pose for beginners": "وضعية الكوبرا للمبتدئين",
  "Collapse individual add-ons on Today by clicking their headers. They start expanded, with progress still visible when collapsed.": "اطوِ الإضافات الفردية في صفحة اليوم بالنقر على عناوينها. وتبدأ موسعة، ويبقى التقدم ظاهرًا عند طيها.",
  "Commit To Life Fitness": "Commit To Life Fitness",
  "Compare {count} styles during today's session. On a phone or rest day, the exercise above opens instead. Hover a number for the style name, or use ‹ › on a phone. Close the switcher with ×.": "قارن بين {count} نمطًا خلال جلسة اليوم. وفي الهاتف أو يوم الراحة يُفتح التمرين أعلاه بدلًا من ذلك. ومرر على الرقم لرؤية اسم النمط، أو استخدم ‹ › على الهاتف. وأغلق المبدل بـ ×.",
  "Compare themes on Today with the switcher at the top. Hover a letter to see the theme name. Close it with ×.": "قارن السمات في صفحة اليوم بالمبدل العلوي. ومرر على الحرف لرؤية اسم السمة. وأغلقه بـ ×.",
  "Complete set {set} of {sets}, then continue to the next movement.": "أكمل المجموعة {set} من {sets}، ثم انتقل إلى الحركة التالية.",
  "Confirm": "تأكيد",
