  "Controlled neck flexion against hand resistance": "ثني رقبي متحكم فيه ضد مقاومة اليد",
  "Controlled vigorous blocks and hard work intervals; brisk beginner intervals are excluded.": "كتل قوية متحكم فيها وفواصل عمل عالية الشدة؛ ولا تُحتسب فواصل المبتدئ السريعة.",
  "Controlled vigorous cardio (indoors)": "كارديو قوي متحكم فيه (داخلي)",
