  "Core exercise: dead bug": "تمرين الجذع: ديد باغ",
  "Cornerstone Physiotherapy": "Cornerstone Physiotherapy",
  "Corrected body, hand, foot and equipment contacts and smoothed exercise motion across animation styles.": "صُححت نقاط تلامس الجسم واليد والقدم والمعدات، ونُعّمت حركة التمارين في أنماط الرسوم المتحركة.",
  "Corrected contacts and movement for dead hangs, hanging leg raises, shoulder taps, Nordic curls, dead bugs, push-ups, tree pose, wall slides, hip CARs and single-leg calf raises.": "صُححت نقاط التلامس والحركة في التعليق الميت، ورفع الساقين معلقًا، ولمس الكتفين، وثني الفخذ النوردي، وديد باغ، وتمارين الضغط، ووضعية الشجرة، والانزلاق على الحائط، ودوران الورك المتحكم فيه، ورفع السمانة بساق واحدة.",
