  "Countermovement jump (Well trained): quick dip with an arm swing, then a max-height jump; stick the landing.": "القفزة بتمهيد عكسي (متقدم): انزل بسرعة مع تأرجح الذراعين، ثم اقفز بأقصى ارتفاع؛ وثبّت الهبوط.",
