  "Follow your level’s heart-rate target, roughly {hr:80-90} at the higher levels. You should be breathing hard and able to say only a few words. Hold an even pace without sprinting.": "اتبع هدف معدل ضربات القلب لمستواك، نحو {hr:80-90} في المستويات الأعلى. يجب أن تتنفس بصعوبة ولا تقدر إلا على بضع كلمات. وحافظ على وتيرة ثابتة دون ركض بأقصى سرعة.",
  "For an easier, quieter version, step sideways onto one leg and hold without hopping.": "لنسخة أسهل وأهدأ، اخطُ جانبًا على ساق واحدة واثبت دون قفز.",
