  "From standing, sit cross-legged onto the floor and rise back up without using hands, knees or arms for support. Scored out of 10.": "من الوقوف، اجلس متربعًا على الأرض ثم انهض دون استخدام اليدين أو الركبتين أو الذراعين للدعم. وتُحتسب الدرجة من 10.",
