  "Hip CARs: 3 slow circles per leg each way (knee up, open out, rotate back, lower).": "دوران الورك المتحكم فيه: 3 دوائر بطيئة لكل ساق في كل اتجاه (ارفع الركبة، افتحها للخارج، أدرها للخلف، ثم أنزلها).",
  "Hip hinge: preparation for the swing": "مفصل الورك: التحضير للمرجحة",
  "Hip-hop": "هيب هوب",
