  "Hips level; don’t push off the floor leg.": "أبقِ الوركين مستويين؛ لا تدفع بالساق الأرضية.",
  "Hips stay square to the floor. Stand back up by squeezing the glute.": "أبقِ الوركين متوازيين مع الأرض. وقف مجددًا بضغط عضلة المؤخرة.",
  "His 2023 version: neck long, chin down, light hand pressure on top of the head, lift the chin about 30° and lower, until fatigue.": "نسخته في 2023: الرقبة ممدودة، والذقن للأسفل، وضغط خفيف باليد على أعلى الرأس، ورفع الذقن نحو 30 درجة ثم إنزاله، حتى الإجهاد.",
  "His 4×4 intervals": "فواصل 4×4 لديه",
  "His five pillars: strength, Zone 2, high-intensity cardio, mobility & flexibility, balance.": "ركائزه الخمس: القوة، والمنطقة 2، والكارديو عالي الشدة، والحركة والمرونة، والتوازن.",
  "His full 2023 routine: backward sled, posture work, step-ups, slant squats, Nordics, tibialis raises, arms, core and stretches. Each exercise link opens at the relevant moment.": "روتينه الكامل في 2023: سحب المزلجة للخلف، وتمارين الوضعية، والصعود على الدرجة، والقرفصاء على لوح مائل، وتمارين نورديك، ورفع الظنبوب، والذراعان، والجذع، والإطالات. ويفتح كل رابط تمرين عند اللحظة المناسبة.",
  "History": "السجل",
  "Hold 1–2 s and lower slowly. Look at the floor so the neck stays long.": "اثبت 1–2 ثانية ثم انزل ببطء. وانظر إلى الأرض لتبقى رقبتك ممدودة.",
  "Hold 3 s, release slowly.": "اثبت 3 ثوانٍ، ثم أرخِ ببطء.",
  "Hold a heavy dumbbell in each hand and stand tall using the string cue. Keep your shoulders down and back.": "أمسك دمبلًا ثقيلًا في كل يد وقف منتصبًا باستخدام إشارة الخيط. وأبقِ كتفيك للأسفل وللخلف.",
  "Hold a light band at shoulder height, arms straight, hands shoulder-width.": "أمسك شريطًا خفيفًا على ارتفاع الكتفين والذراعان مستقيمتان واليدان بعرض الكتفين.",
  "Hold a light dumbbell ({kg:1-4}) and rotate the forearm up and back as far as is comfortable.": "أمسك دمبلًا خفيفًا ({kg:1-4}) وأدر الساعد للأعلى وللخلف بقدر ما هو مريح.",
  "Hold for 2 s without tilting your hips, then return and switch sides.": "اثبت ثانيتين دون إمالة الوركين، ثم عد وبدّل الجهة.",
  "Hold for the time your level prescribes, then progress to eyes closed.": "اثبت للمدة التي يحددها مستواك، ثم تقدم إلى إغماض العينين.",
  "Hold one dumbbell vertically against your chest.": "أمسك دمبلًا واحدًا عموديًا على صدرك.",
  "Hold one dumbbell with both hands overhead, elbows pointing forward.": "أمسك دمبلًا واحدًا بكلتا يديك فوق رأسك والمرفقان للأمام.",
  "hold one in each hand and press from your shoulders until your arms are straight.": "أمسك دمبلًا في كل يد واضغط من كتفيك حتى تستقيم ذراعاك.",
  "Hold onto a wall or sturdy chair for balance, or reduce heel lift to 1–2 cm.": "أمسك بحائط أو كرسي ثابت للتوازن، أو قلل رفع الكعب إلى 1–2 سم.",
  "Hold the band at your sternum with both hands, knees soft.": "أمسك الشريط عند عظمة القص بكلتا يديك والركبتان لينتان.",
  "Hold the dumbbells in front of your thighs with your knees slightly bent.": "أمسك الدمبل أمام فخذيك مع ثني الركبتين قليلًا.",
