  "Howcast": "Howcast",
  "Ideally up to 20–24 kg each, so the RDL, goblet squat and carries keep progressing.": "يُفضّل أن يصل وزن كل دمبل إلى 20–24 كجم، لتستمر الرفعة الرومانية وقرفصاء الكأس والحمل في التقدم.",
  "If round 4 falls apart, start slower next time. Don’t sprint the first minute.": "إذا تفككت الجولة الرابعة، فابدأ أبطأ في المرة القادمة. ولا تركض بأقصى سرعة في الدقيقة الأولى.",
  "If workouts feel too hard or you're returning after a break, you can switch to {level}.": "إذا شعرت أن التمارين صعبة جدًا أو كنت عائدًا بعد انقطاع، فيمكنك التبديل إلى {level}.",
  "If you cannot do 5 clean reps, use a band for assistance, or jump up and lower over 5 s (negatives).": "إذا لم تستطع أداء 5 تكرارات نظيفة، فاستخدم شريطًا للمساعدة، أو اقفز للأعلى وانزل خلال 5 ثوانٍ (تكرارات سلبية).",
  "If you don't have an item, see the easier exercises and equipment swaps in": "إذا لم تملك أحد العناصر، فراجع التمارين الأسهل وبدائل المعدات في",
  "If you have been inactive for a while, are over 50 or have any heart condition, get a basic check-up (blood pressure, resting ECG) before your first all-out intervals.": "إذا كنت غير نشط لفترة، أو تجاوزت 50 عامًا، أو لديك أي حالة قلبية، فاحصل على فحص أساسي (ضغط الدم وتخطيط القلب أثناء الراحة) قبل أول فواصل بأقصى جهد.",
  "Imagine the string lifting the crown of your head: chin level, neck long.": "تخيل الخيط يرفع تاج رأسك: الذقن بمستوى أفقي والرقبة ممدودة.",
