  "In Bryan’s routine at 3 × 10. This Knees-Over-Toes exercise combines a deep bend of the front knee with a stretch of the back hip flexor.": "في روتين براين بـ3 × 10. يجمع تمرين «الركبتين فوق أصابع القدم» بين ثني الركبة الأمامية بعمق وإطالة مثنيات الورك الخلفية.",
