  "Longevity benchmarks & fitness age: A dedicated Benchmarks view in Activity tracking the 8 core zero-blood physical biomarkers from Bryan Johnson's published battery (continuous push-ups, handgrip strength, dead hang, eyes-closed balance, sit-and-rise, VO2 Max, sit & reach, and heart-rate recovery drop), with ratings and monthly or quarterly cadence.": "معايير طول العمر وعمر اللياقة: عرض مخصص للمعايير في النشاط يتتبع المؤشرات البدنية الثمانية الأساسية دون سحب دم من بطارية براين جونسون المنشورة (الضغط المتواصل، وقوة قبضة اليد، والتعليق الميت، والتوازن بعينين مغمضتين، والجلوس والنهوض، والحد الأقصى لاستهلاك الأكسجين، والجلوس والوصول، وانخفاض معدل ضربات القلب بعد التمرين)، مع تقييمات وإيقاع شهري أو ربع سنوي.",
