  "Lower forward as slowly as you can and catch yourself with your hands, like a push-up.": "انزل للأمام بأبطأ ما يمكنك واحتجز نفسك بيديك، مثل تمرين الضغط.",
  "Lower in 2 s. Don’t lean back.": "انزل خلال ثانيتين. لا تمل للخلف.",
  "Lower in 2–3 s to a full hang.": "انزل خلال 2–3 ثوانٍ إلى تعليق كامل.",
