  "Lower slowly. Collect the reps in as few sets as you can.": "انزل ببطء. ووزّع التكرارات على أقل عدد ممكن من المجموعات.",
  "Lower slowly. Drive up under control; do not jump onto an aerobic step or stack loose risers or furniture.": "انزل ببطء. واصعد بتحكم؛ لا تقفز على درجة هوائية أو تكدس رفعات أو أثاثًا غير ثابت.",
  "Lower the other heel slowly to the floor in front by bending the working knee far over the toes.": "اخفض الكعب الآخر ببطء إلى الأرض أمامك بثني الركبة العاملة كثيرًا فوق أصابع القدم.",
