  "place your hands on the mat. Use it for planks, floor work and stretches too.": "ضع يديك على الحصيرة. واستخدمها أيضًا للبلانك وتمارين الأرض والإطالات.",
  "Place your whole foot on the step. Push through that leg until you stand tall.": "ضع قدمك كاملة على الدرجة. وادفع بتلك الساق حتى تقف منتصبًا.",
  "Plan": "الخطة",
  "Plan change:": "تغيير الخطة:",
  "Plan change: Clarified the setup notes for ATG split squats, single-leg toe touches, band pull-aparts, standing external rotation, side planks and side-to-side leg swings.": "تغيير الخطة: وُضحت ملاحظات الإعداد لقرفصاء ATG المنقسمة، ولمس القدم بساق واحدة، وفتح المطاط، والدوران الخارجي واقفًا، والبلانك الجانبي، وتأرجح الساق جانبيًا.",
  "Plan change: Scheduled Zone 2 and controlled vigorous cardio scale by level toward Bryan’s weekly targets of 150 minutes of Zone 2 and 75 minutes of hard cardio.": "تغيير الخطة: المنطقة المجدولة 2 ومقياس تمارين القلب القوي الذي يتم التحكم فيه حسب المستوى نحو أهداف براين الأسبوعية البالغة 150 دقيقة من المنطقة 2 و75 دقيقة من تمارين القلب القاسية.",
  "Plan change: Step-ups use a low aerobic step; Poliquin heel taps start on a slant board on the floor, with matching animations.": "تغيير الخطة: يستخدم الصعود على الدرجة درجة هوائية منخفضة؛ وتبدأ لمسات كعب بوليكين على لوح مائل على الأرض، مع رسوم متحركة مطابقة.",
  "Plan change: Your training level alone now sets the workouts. Each of the four levels (New to training, Returning, Active, Well trained) has its own sets, reps, intervals and Zone 2 minutes; nothing moves on by itself. Your weight, sex and age still scale the suggested weights.": "تغيير الخطة: أصبح مستوى تدريبك وحده يحدد التمارين. ولكل مستوى من المستويات الأربعة (مبتدئ، عائد، نشط، متقدم) مجموعاته وتكراراته وفواصله ودقائق المنطقة 2 الخاصة به؛ ولا شيء يتقدم من تلقاء نفسه. ولا يزال وزنك وجنسك وعمرك يعدلون الأوزان المقترحة.",
  "Plan changed": "تم تغيير الخطة",
