  "Single-leg toe touches for balance (beginners)": "لمسات القدم بساق واحدة للتوازن (للمبتدئين)",
  "Sit & Reach Flexibility": "مرونة الجلوس والوصول",
  "Sit back gently toward the heels; take weight on your hands to adjust.": "اجلس للخلف بلطف نحو الكعبين؛ وحمّل بعض وزنك على يديك للتعديل.",
  "Sit back toward your heels.": "اجلس للخلف نحو كعبيك.",
  "Sit on the floor, legs straight out in front. Reach smoothly forward along your shins toward your toes. Measure how many cm past toes you can reach (negative if short).": "اجلس على الأرض وساقاك ممدودتان أمامك. ومد يديك بسلاسة للأمام على طول الساقين نحو أصابع القدمين. وقس عدد السنتيمترات التي تتجاوز بها أصابع قدميك (وتكون سالبة إن لم تصل).",
  "Sit or stand tall (string cue), chin slightly tucked so the back of the neck is long.": "اجلس أو قف منتصبًا (إشارة الخيط)، مع سحب الذقن قليلًا ليكون خلف الرقبة ممدودًا.",
  "Sit or stand tall, eyes level.": "اجلس أو قف منتصبًا وعيناك بمستوى أفقي.",
  "Sit straight down to full depth with your torso upright. Let your knees travel well past your toes.": "انزل مستقيمًا إلى العمق الكامل وجذعك منتصب. ودع ركبتيك تتجاوزان أصابع القدم بمسافة واضحة.",
  "Sit tall, soles of the feet together, knees falling out.": "اجلس منتصبًا وأخمصا القدمين متلاصقان والركبتان تنزلان للخارج.",
  "Sit-and-Rise Test (SRT)": "اختبار الجلوس والنهوض (SRT)",
