  "UK dance": "رقص بريطاني",
  "Unbroken passive or active hang from a pull-up bar. Longevity benchmark: 60 to 120 seconds.": "تعليق سلبي أو نشط متواصل من بار العقلة. ومعيار طول العمر: 60 إلى 120 ثانية.",
