  "Upper body endurance": "قدرة تحمل الجزء العلوي",
  "Use {level}": "استخدام مستوى {level}",
  "Use a band or controlled negatives when prescribed.": "استخدم الشريط المطاطي أو السلبيات الخاضعة للرقابة عند وصفها.",
  "Use a full http:// or https:// product link.": "استخدم رابط منتج كاملًا يبدأ بـ http:// أو https://.",
  "Use a stable aerobic step or stair, starting at its lowest secure height. A low step is the home adaptation of Bryan’s step-up.": "استخدم درجة هوائية أو سلمًا ثابتًا، وابدأ من أدنى ارتفاع آمن. والدرجة المنخفضة هي النسخة المنزلية من صعود براين.",
  "Use Active": "استخدام مستوى نشط",
  "Use Galpin-style heavy work for the main lifts and follow Friday’s RDL sets with jumps.": "استخدم العمل الثقيل بأسلوب جالبين للرفعات الأساسية، واتبع مجموعات الرفعة الرومانية يوم الجمعة بالقفزات.",
  "Use one dumbbell with a secure two-handed grip, feet a bit wider than the hips. With an adjustable kit, use swings only if its manual permits dynamic use and all fasteners are locked.": "استخدم دمبلًا واحدًا بقبضة ثابتة بكلتا يديك، والقدمان أوسع قليلًا من الوركين. مع مجموعة قابلة للتعديل، استخدم المرجحة فقط إذا كان دليلها يسمح بالاستخدام الديناميكي وكانت جميع أدوات التثبيت مقفلة.",
  "Use Returning": "استخدام مستوى عائد",
