  "Videos in guided mode scroll with the panel instead of staying pinned over the list below.": "تتحرك الفيديوهات في الوضع الموجه مع اللوحة بدلًا من البقاء مثبتة فوق القائمة أدناه.",
  "View product": "عرض المنتج",
  "Vigorous cardio shows its own fast-pace demo with matching coach cues instead of the Zone 2 \"talking pace\" lines; the marching-on-the-spot cue no longer mentions round counting.": "يعرض الكارديو عالي الشدة نموذجًا سريعًا خاصًا به مع إشارات مدرب مطابقة بدلًا من عبارات «وتيرة التحدث» في المنطقة 2؛ ولم تعد إشارة المشي في المكان تذكر عد الجولات.",
