  "Voice cache paused: {error} Turn coaching on again to retry; finished audio is kept.": "توقف تحضير ذاكرة الصوت مؤقتًا: {error} فعّل التدريب الصوتي مجددًا لإعادة المحاولة؛ ويُحتفظ بالصوت المكتمل.",
