  "VRM avatars with MToon shading": "صور VRM الرمزية بتظليل MToon",
  "Walk around the room with slow, steady steps for 30–40 s.": "امشِ في الغرفة بخطوات بطيئة وثابتة لمدة 30–40 ثانية.",
  "Walk backward for 2 min along a clear stretch of hallway or living room. Turn around when you reach the wall.": "امشِ للخلف دقيقتين في ممر واضح أو غرفة المعيشة. واستدر قبل أن تصل إلى الحائط.",
  "Walking lunge with twist tutorial": "دليل الاندفاع مع اللف أثناء المشي",
  "Wall slides": "الانزلاق على الحائط",
  "Wall slides for thoracic mobility and posture": "الانزلاق على الحائط لحركية الصدر والوضعية",
  "Wall tibialis raise": "رفع الظنبوب على الحائط",
  "Wall tibialis raises": "رفع الظنبوب على الحائط",
  "Wall-supported drills keep the supporting hand planted the whole time (leg swings and standing hip CARs), and hip CARs circle both directions as the steps describe.": "تحافظ التدريبات المدعومة على الحائط على اليد الداعمة مثبتة طوال الوقت (أرجحة الساق ودوران الورك المتحكم فيه الواقفة)، وتدور دوران الورك المتحكم فيه في كلا الاتجاهين كما هو موضح في الخطوات.",
  "Wall-supported standing hip CARs": "دوران الورك المتحكم فيه الدائمة المدعومة بالحائط",
  "Warm up first. Use continuous low-step step-ups, fast marching, high knees or step jacks, changing the move before local muscle fatigue spoils your form.": "أحمِ أولًا. استخدم صعودًا متواصلًا على درجة منخفضة، أو مشيًا سريعًا، أو رفع الركبتين، أو فتح وإغلاق بخطوة، وبدّل الحركة قبل أن يفسد إجهاد العضلات الموضعي أداءك.",
  "Warm up gently for 10 min, building to about {hr:71}.": "أحمِ ببطء لمدة 10 دقائق، وصولًا إلى نحو {hr:71}.",
  "Warm-up": "الإحماء",
  "Warm-up & balance": "الإحماء والتوازن",
  "Warm-up, then speed and power (2 × 5), strength (2 × 5–8), posture, conditioning and flexibility (5 × 30 s). In Feb 2025, he reported a VO2 max personal best of 64.29.": "الإحماء، ثم السرعة والقوة (2 × 5)، والقوة (2 × 5–8)، والوضعية، والتكييف والمرونة (5 × 30 ثانية). وفي فبراير 2025 سجل أفضل رقم شخصي في الحد الأقصى لاستهلاك الأكسجين بلغ 64.29.",
  "Wear shoes and land on a mat. Stop the set if your landings get loud.": "ارتدِ حذاءً واهبط على حصيرة. أوقف المجموعة إذا صار صوت الهبوط عاليًا.",
  "Wed": "الأربعاء",
  "Wednesday": "الأربعاء",
