  "Weekly targets compare your level and Bryan's full week in one card.": "تقارن الأهداف الأسبوعية مستواك وأسبوع براين الكامل في بطاقة واحدة.",
  "Weekly targets for your level; open This week for the full Bryan comparison": "الأهداف الأسبوعية لمستواك؛ افتح «هذا الأسبوع» لمقارنة براين الكاملة",
