  "Weighted vest": "سترة مثقلة",
  "Welcome": "مرحبًا",
  "Well trained": "متقدم",
  "Well trained contrast: 20–30 s after each set, do 3 max countermovement jumps, the way Bryan pairs his heavy pulls with jumps.": "تباين مستوى المتقدم: بعد 20–30 ثانية من كل مجموعة، نفّذ 3 قفزات بتمهيد عكسي بأقصى ارتفاع، كما يقرن براين سحباته الثقيلة بالقفزات.",
  "Well trained is the top level. After illness, injury or a long break, the plan says step down for a while.": "مستوى متقدم هو الأعلى. وبعد المرض أو الإصابة أو انقطاع طويل، تنصح الخطة بالنزول مستوى لبعض الوقت.",
  "Well trained meets his full weekly targets. Lower levels build toward them.": "يحقق مستوى متقدم أهدافه الأسبوعية الكاملة. وتبني المستويات الأدنى نحوها.",
  "Wellen": "Wellen",
  "Whats Up Dude": "Whats Up Dude",
  "When you get the chance, a brisk walk, hike or bike ride outside counts the same.": "عندما تسنح لك الفرصة، يُحتسب المشي السريع أو التنزه أو ركوب الدراجة في الخارج بالمثل.",
  "Where are you starting from?": "من أي مستوى تبدأ؟",
  "Why days were skipped": "أسباب تخطي الأيام",
  "Will Wayland: How I’d train Bryan Johnson to vertical jump": "ويل وايلاند: كيف أدرب براين جونسون على القفز العمودي",
  "With notes": "مع ملاحظات",
