  "You can speak in full sentences: Bryan’s 150 min/week": "يمكنك التحدث بجمل كاملة: براين 150 دقيقة/أسبوع",
  "You cannot talk: the end of 20 s bursts and each 4×4 round": "لا يمكنك التحدث: نهاية رشقات 20 ثانية وكل جولة 4×4",
  "You finished each one without needing to stop early.": "أكملت كل جلسة دون حاجة إلى التوقف مبكرًا.",
