  "You've completed {count} sessions at this level. Past workouts keep the level you logged them at.": "أكملت {count} جلسة في هذا المستوى. تحتفظ التمارين السابقة بالمستوى الذي سجلتها فيه.",
  "You've completed 0 sessions at this level. Past workouts keep the level you logged them at.": "أكملت 0 جلسة في هذا المستوى. تحتفظ التمارين السابقة بالمستوى الذي سجلتها فيه.",
  "You've completed 1 session at this level. Past workouts keep the level you logged them at.": "أكملت جلسة واحدة في هذا المستوى. تحتفظ التمارين السابقة بالمستوى الذي سجلتها فيه.",
