  "Your data saves to": "تُحفظ بياناتك في",
  "Your data saves to <code>{dir}/</code> on this computer. Git ignores this folder. Copy it or export a backup below to keep a spare copy.": "تُحفظ بياناتك في <code>{dir}/</code> على هذا الجهاز. يتجاهل Git هذا المجلد. انسخه أو صدّر نسخة احتياطية أدناه للاحتفاظ بنسخة إضافية.",
  "Your details": "بياناتك",
  "Your details and workouts are saved in this browser because the local server isn't running. Run": "تُحفظ بياناتك وتمارينك في هذا المتصفح لأن الخادم المحلي لا يعمل. شغّل",
  "Your details and workouts are saved in this browser because the local server isn't running. Run <code>npm start</code> to save them as files.": "تُحفظ بياناتك وتمارينك في هذا المتصفح لأن الخادم المحلي لا يعمل. شغّل <code>npm start</code> لحفظها كملفات.",
  "Your details and workouts save in the": "تُحفظ بياناتك وتمارينك في",
  "Your details and workouts save in the <code>{dir}/</code> folder on this computer.": "تُحفظ بياناتك وتمارينك في مجلد <code>{dir}/</code> على هذا الجهاز.",
  "Your details set your suggested starting weights and heart-rate zones: max {bpm} bpm, Zone 2 {range}.": "تحدد بياناتك أوزان البدء المقترحة ومناطق معدل ضربات القلب: الحد الأقصى {bpm} نبضة/دقيقة، والمنطقة 2 {range}.",
  "Your details set your suggested starting weights and heart-rate zones: max 187 bpm, Zone 2 112–131 bpm.": "تحدد بياناتك أوزان البدء المقترحة ومناطق معدل ضربات القلب: الحد الأقصى 187 نبضة/دقيقة، والمنطقة 2 112–131 نبضة/دقيقة.",
  "Your equipment": "معداتك",
  "Your equipment list is optional. Tick what you own, then add a name and optional product link. You can add equivalent equipment below. These details stay in your inventory; exercise instructions use generic names.": "قائمة معداتك اختيارية. حدّد ما تملكه، ثم أضف اسمًا ورابط منتج إن أردت. يمكنك إضافة معدات مكافئة أدناه. تبقى هذه التفاصيل في قائمتك؛ وتستخدم تعليمات التمارين أسماء عامة.",
