  "Your week: Mon, strength; Tue, short intervals and Zone 2; Wed, strength and mobility; Thu, Norwegian 4×4 and stability; Fri, power and strength; Sat, controlled vigorous cardio, Zone 2 and a long stretch; Sun, rest.": "أسبوعك: الإثنين قوة؛ الثلاثاء فواصل قصيرة والمنطقة 2؛ الأربعاء قوة وحركة؛ الخميس 4×4 النرويجي وثبات؛ الجمعة قوة انفجارية وقوة؛ السبت كارديو قوي متحكم فيه والمنطقة 2 وإطالة طويلة؛ الأحد راحة.",
