  "Your workout is complete. You can record how it felt in your notes.": "اكتمل تمرينك. يمكنك تدوين إحساسك به في ملاحظاتك.",
  "Your workouts include the scheduled cardio. Extra activity is optional. Lower levels build toward Bryan's weekly targets. At Well trained, sessions take about 72 to 93 minutes (8.2 hours a week) with all strength and mobility work, before add-ons or extra recovery breaks. The extra vigorous cardio and Zone 2 time adapt his weekly targets for this home plan.": "تتضمن تمارينك الكارديو المجدول. والنشاط الإضافي اختياري. وتبني المستويات الأدنى نحو أهداف براين الأسبوعية. وفي مستوى متقدم تستغرق الجلسات نحو 72 إلى 93 دقيقة (8.2 ساعة أسبوعيًا) مع كل عمل القوة والحركة، قبل الإضافات أو فترات الاسترداد الإضافية. ويكيّف الكارديو القوي الإضافي ووقت المنطقة 2 أهدافه الأسبوعية مع هذه الخطة المنزلية.",
